from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .errors import ParseError, AggregateError, ArityError
from .lexer import Token, tokenize


@dataclass(frozen=True)
class Literal:
    value: object


@dataclass(frozen=True)
class ColumnRef:
    name: str
    table: str | None = None


@dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: Any


@dataclass(frozen=True)
class BinaryOp:
    op: str
    left: Any
    right: Any


@dataclass(frozen=True)
class FunctionCall:
    name: str
    args: list[Any]


@dataclass(frozen=True)
class NullCheck:
    expr: Any
    op: str


@dataclass(frozen=True)
class Star:
    table: str | None = None


@dataclass(frozen=True)
class SelectItem:
    expr: Any
    alias: str | None = None


@dataclass(frozen=True)
class JoinSpec:
    table: str
    kind: str
    on: Any


@dataclass(frozen=True)
class Query:
    distinct: bool
    select_items: list[SelectItem]
    from_table: str
    join: JoinSpec | None
    where: Any | None
    group_by: list[Any]
    having: Any | None
    order_by: list[tuple[Any, str]]
    limit: int | None
    offset: int | None


class Parser:
    def __init__(self, text: str) -> None:
        self.tokens = tokenize(text)
        self.index = 0

    def parse(self) -> Query:
        self._expect("SELECT")
        distinct = self._match("DISTINCT")
        items = self._select_items()
        self._expect("FROM")
        table = self._ident()
        join = self._parse_join()
        where = self._parse_clause("WHERE")
        group_by = self._parse_group_by()
        having = self._parse_clause("HAVING")
        order_by = self._parse_order_by()
        limit = self._parse_limit()
        offset = self._parse_offset()
        self._expect("EOF")
        return Query(distinct, items, table, join, where, group_by, having, order_by, limit, offset)

    def _select_items(self) -> list[SelectItem]:
        items: list[SelectItem] = []
        while True:
            if self._match("*"):
                items.append(SelectItem(Star()))
            elif self._peek_kind() == "IDENT":
                name = self._ident()
                if self._match(".") and self._peek_kind() == "*":
                    self._expect("*")
                    items.append(SelectItem(Star(name)))
                else:
                    expr = self._parse_expr_after_ident(name)
                    alias = None
                    if self._match("AS"):
                        alias = self._ident()
                    items.append(SelectItem(expr, alias))
            else:
                expr = self._parse_expr()
                alias = None
                if self._match("AS"):
                    alias = self._ident()
                items.append(SelectItem(expr, alias))
            if not self._match(","):
                return items

    def _parse_expr_after_ident(self, name: str) -> Any:
        if self._peek_kind() == "(":
            self._expect("(")
            args: list[Any] = []
            if not self._match(")"):
                while True:
                    if self._peek_kind() == "*":
                        self._advance()
                        args.append(Star())
                    else:
                        args.append(self._parse_expr())
                    if self._match(")"):
                        break
                    self._expect(",")
            return FunctionCall(name, args)
        if self._match("."):
            right = self._ident()
            return ColumnRef(right, name)
        return ColumnRef(name)

    def _parse_join(self) -> JoinSpec | None:
        if self._peek_kind() == "INNER":
            self._advance()
            self._expect("JOIN")
            table = self._ident()
            self._expect("ON")
            return JoinSpec(table, "INNER", self._parse_expr())
        if self._peek_kind() == "LEFT":
            self._advance()
            self._expect("JOIN")
            table = self._ident()
            self._expect("ON")
            return JoinSpec(table, "LEFT", self._parse_expr())
        if self._peek_kind() == "JOIN":
            self._advance()
            table = self._ident()
            self._expect("ON")
            return JoinSpec(table, "INNER", self._parse_expr())
        return None

    def _parse_clause(self, keyword: str) -> Any | None:
        if self._peek_kind() != keyword:
            return None
        self._advance()
        return self._parse_expr()

    def _parse_group_by(self) -> list[Any]:
        if self._peek_kind() != "GROUP":
            return []
        self._advance()
        self._expect("BY")
        items = [self._parse_expr()]
        while self._match(","):
            items.append(self._parse_expr())
        return items

    def _parse_order_by(self) -> list[tuple[Any, str]]:
        if self._peek_kind() != "ORDER":
            return []
        self._advance()
        self._expect("BY")
        items: list[tuple[Any, str]] = []
        while True:
            expr = self._parse_expr()
            direction = "ASC"
            if self._peek_kind() in {"ASC", "DESC"}:
                direction = self._advance().kind
            items.append((expr, direction))
            if not self._match(","):
                return items

    def _parse_limit(self) -> int | None:
        if self._peek_kind() != "LIMIT":
            return None
        self._advance()
        value = self._expect_number()
        return int(value)

    def _parse_offset(self) -> int | None:
        if self._peek_kind() != "OFFSET":
            return None
        self._advance()
        value = self._expect_number()
        return int(value)

    def _parse_expr(self) -> Any:
        return self._parse_or()

    def _parse_or(self) -> Any:
        expr = self._parse_and()
        while self._match("OR"):
            expr = BinaryOp("OR", expr, self._parse_and())
        return expr

    def _parse_and(self) -> Any:
        expr = self._parse_not()
        while self._match("AND"):
            expr = BinaryOp("AND", expr, self._parse_not())
        return expr

    def _parse_not(self) -> Any:
        if self._match("NOT"):
            return UnaryOp("NOT", self._parse_not())
        return self._parse_predicate()

    def _parse_predicate(self) -> Any:
        expr = self._parse_additive()
        if self._peek_kind() == "IS":
            self._advance()
            if self._match("NOT"):
                self._expect("NULL")
                return NullCheck(expr, "IS NOT NULL")
            self._expect("NULL")
            return NullCheck(expr, "IS NULL")
        if self._peek_kind() in {"=", "<>", "<", "<=", ">", ">="}:
            op = self._advance().kind
            right = self._parse_additive()
            if self._peek_kind() in {"=", "<>", "<", "<=", ">", ">="}:
                raise ParseError(self._peek().offset)
            return BinaryOp(op, expr, right)
        return expr

    def _parse_additive(self) -> Any:
        expr = self._parse_multiplicative()
        while self._peek_kind() in {"+", "-"}:
            op = self._advance().kind
            expr = BinaryOp(op, expr, self._parse_multiplicative())
        return expr

    def _parse_multiplicative(self) -> Any:
        expr = self._parse_unary()
        while self._peek_kind() in {"*", "/", "%"}:
            op = self._advance().kind
            expr = BinaryOp(op, expr, self._parse_unary())
        return expr

    def _parse_unary(self) -> Any:
        if self._match("-"):
            return UnaryOp("-", self._parse_unary())
        return self._parse_primary()

    def _parse_primary(self) -> Any:
        kind = self._peek_kind()
        if kind == "NUMBER":
            tok = self._advance()
            return Literal(tok.value)
        if kind in {"TEXT", "TRUE", "FALSE", "NULL"}:
            tok = self._advance()
            if tok.kind == "TEXT":
                return Literal(tok.value)
            if tok.kind == "TRUE":
                return Literal(True)
            if tok.kind == "FALSE":
                return Literal(False)
            return Literal(None)
        if kind == "IDENT":
            name = self._ident()
            if self._match("("):
                args: list[Any] = []
                if not self._match(")"):
                    while True:
                        if self._peek_kind() == "*":
                            self._advance()
                            args.append(Star())
                        else:
                            args.append(self._parse_expr())
                        if self._match(")"):
                            break
                        self._expect(",")
                return FunctionCall(name, args)
            if self._match("."):
                right = self._ident()
                return ColumnRef(right, name)
            return ColumnRef(name)
        if self._match("("):
            expr = self._parse_expr()
            self._expect(")")
            return expr
        raise ParseError(self._peek().offset)

    def _peek(self) -> Token:
        return self.tokens[self.index]

    def _peek_kind(self) -> str:
        return self.tokens[self.index].kind

    def _advance(self) -> Token:
        tok = self.tokens[self.index]
        self.index += 1
        return tok

    def _match(self, kind: str) -> bool:
        if self._peek_kind() == kind:
            self.index += 1
            return True
        return False

    def _expect(self, kind: str) -> Token:
        if self._peek_kind() != kind:
            raise ParseError(self._peek().offset)
        return self._advance()

    def _expect_number(self) -> int:
        tok = self._expect("NUMBER")
        value = tok.value
        if not isinstance(value, (int, float)):
            raise ParseError(tok.offset)
        if isinstance(value, float):
            if int(value) != value:
                raise ParseError(tok.offset)
            return int(value)
        return int(value)

    def _ident(self) -> str:
        tok = self._expect("IDENT")
        return str(tok.value)


def parse(text: str) -> Query:
    return Parser(text).parse()

from __future__ import annotations

from .aggregate import AGGREGATE_NAMES
from .errors import AggregateError, AmbiguousColumnError, ArityError, TypeMismatchError, UnknownColumnError, UnknownFunctionError, UnknownTableError
from .parser import BinaryOp, ColumnRef, FunctionCall, Literal, NullCheck, Star, UnaryOp
from .value import and_, arith, compare_eq, compare_lt, negate, not_, or_, type_of


def evaluate(expr: object, row: dict[str, object]) -> object:
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return _resolve_ref(row, expr)
    if isinstance(expr, UnaryOp):
        return _eval_unary(expr.op, expr.operand, row)
    if isinstance(expr, BinaryOp):
        return _eval_binary(expr.op, expr.left, expr.right, row)
    if isinstance(expr, FunctionCall):
        return _eval_call(expr, row)
    if isinstance(expr, NullCheck):
        return _eval_null_check(expr, row)
    if isinstance(expr, Star):
        return None
    raise TypeMismatchError("unsupported expression")


def _resolve_ref(row: dict[str, object], expr: ColumnRef) -> object:
    name = expr.name
    if expr.table is not None:
        key = f"{expr.table}.{name}"
        if key in row:
            return row[key]
        raise UnknownTableError(expr.table)
    ambig = row.get("__ambig__", set())
    if name in ambig:
        raise AmbiguousColumnError(name)
    if name in row:
        return row[name]
    src = row.get("__source__")
    if isinstance(src, dict):
        if name in src.get("__ambig__", set()):
            raise AmbiguousColumnError(name)
        if name in src:
            return src[name]
    raise UnknownColumnError(name)


def _eval_unary(op: str, operand: object, row: dict[str, object]) -> object:
    value = evaluate(operand, row)
    if op == "-":
        return negate(value)
    if op == "NOT":
        if not isinstance(value, bool) and value is not None:
            raise TypeMismatchError("NOT requires logical operand")
        return not_(value if value is None or isinstance(value, bool) else None)
    raise TypeMismatchError("unsupported unary op")


def _eval_binary(op: str, left: object, right: object, row: dict[str, object]) -> object:
    lv = evaluate(left, row)
    rv = evaluate(right, row)
    if op == "AND":
        if lv is not None and not isinstance(lv, bool):
            raise TypeMismatchError("AND requires bool")
        if rv is not None and not isinstance(rv, bool):
            raise TypeMismatchError("AND requires bool")
        return and_(lv, rv)
    if op == "OR":
        if lv is not None and not isinstance(lv, bool):
            raise TypeMismatchError("OR requires bool")
        if rv is not None and not isinstance(rv, bool):
            raise TypeMismatchError("OR requires bool")
        return or_(lv, rv)
    if op in {"=", "<>", "<", "<=", ">", ">="}:
        return _compare(op, lv, rv)
    if op in {"+", "-", "*", "/", "%"}:
        return arith(op, lv, rv)
    raise TypeMismatchError("unsupported binary op")


def _compare(op: str, left: object, right: object) -> object:
    if op == "=":
        return compare_eq(left, right)
    if op == "<>":
        eq = compare_eq(left, right)
        if eq is None:
            return None
        return not eq
    if op == "<":
        return compare_lt(left, right)
    if op == "<=":
        lt = compare_lt(left, right)
        eq = compare_eq(left, right)
        if lt is None or eq is None:
            return None
        return lt or eq
    if op == ">":
        lt = compare_lt(right, left)
        return lt
    if op == ">=":
        lt = compare_lt(right, left)
        eq = compare_eq(left, right)
        if lt is None or eq is None:
            return None
        return lt or eq
    raise TypeMismatchError("unsupported comparator")


def _eval_call(expr: FunctionCall, row: dict[str, object]) -> object:
    name = expr.name.lower()
    if name in AGGREGATE_NAMES:
        raise AggregateError(f"aggregate {name} not allowed here")
    if name == "concat":
        return _call_concat(expr.args, row)
    if name in {"upper", "lower"}:
        return _call_text(expr.args, row, name)
    if name == "length":
        return _call_length(expr.args, row)
    if name == "abs":
        return _call_abs(expr.args, row)
    if name == "coalesce":
        return _call_coalesce(expr.args, row)
    raise UnknownFunctionError(name)


def _eval_null_check(expr: NullCheck, row: dict[str, object]) -> bool | None:
    value = evaluate(expr.expr, row)
    if expr.op == "IS NULL":
        return value is None
    return value is not None


def _call_concat(args: list[object], row: dict[str, object]) -> object:
    values = [evaluate(a, row) for a in args]
    if len(values) < 2:
        raise ArityError("concat requires at least 2 args")
    for value in values:
        if value is None:
            return None
        if not isinstance(value, str):
            raise TypeMismatchError("concat requires TEXT")
    return "".join(values)


def _call_text(args: list[object], row: dict[str, object], name: str) -> object:
    if len(args) != 1:
        raise ArityError(f"{name} requires 1 arg")
    value = evaluate(args[0], row)
    if value is None:
        return None
    if not isinstance(value, str):
        raise TypeMismatchError(f"{name} requires TEXT")
    return value.upper() if name == "upper" else value.lower()


def _call_length(args: list[object], row: dict[str, object]) -> object:
    if len(args) != 1:
        raise ArityError("length requires 1 arg")
    value = evaluate(args[0], row)
    if value is None:
        return None
    if not isinstance(value, str):
        raise TypeMismatchError("length requires TEXT")
    return len(value)


def _call_abs(args: list[object], row: dict[str, object]) -> object:
    if len(args) != 1:
        raise ArityError("abs requires 1 arg")
    value = evaluate(args[0], row)
    if value is None:
        return None
    if value is None or isinstance(value, bool):
        raise TypeMismatchError("abs requires numeric")
    if isinstance(value, int):
        return abs(value)
    if isinstance(value, float):
        return abs(value)
    raise TypeMismatchError("abs requires numeric")


def _call_coalesce(args: list[object], row: dict[str, object]) -> object:
    if not args:
        raise ArityError("coalesce requires at least 1 arg")
    for arg in args:
        value = evaluate(arg, row)
        if value is not None:
            return value
    return None


def contains_aggregate(expr: object) -> bool:
    if isinstance(expr, FunctionCall):
        if expr.name.lower() in AGGREGATE_NAMES:
            return True
        return any(contains_aggregate(arg) for arg in expr.args)
    if isinstance(expr, UnaryOp):
        return contains_aggregate(expr.operand)
    if isinstance(expr, BinaryOp):
        return contains_aggregate(expr.left) or contains_aggregate(expr.right)
    if isinstance(expr, NullCheck):
        return contains_aggregate(expr.expr)
    return False


def expr_label(expr: object) -> str:
    if isinstance(expr, Literal):
        if expr.value is None:
            return "NULL"
        if isinstance(expr.value, bool):
            return "TRUE" if expr.value else "FALSE"
        return str(expr.value)
    if isinstance(expr, ColumnRef):
        return f"{expr.table}.{expr.name}" if expr.table else expr.name
    if isinstance(expr, UnaryOp):
        return f"{expr.op} {expr_label(expr.operand)}"
    if isinstance(expr, BinaryOp):
        return f"{expr_label(expr.left)} {expr.op} {expr_label(expr.right)}"
    if isinstance(expr, FunctionCall):
        parts = [expr.name]
        parts.append("(")
        args = []
        for arg in expr.args:
            if isinstance(arg, Star):
                args.append("*")
            else:
                args.append(expr_label(arg))
        parts.append(", ".join(args))
        parts.append(")")
        return "".join(parts)
    if isinstance(expr, NullCheck):
        return f"{expr_label(expr.expr)} {expr.op}"
    return "expr"

from __future__ import annotations

from .errors import TypeMismatchError
from .value import compare_lt

AGGREGATE_NAMES = {"count", "sum", "avg", "min", "max"}


def aggregate_value(name: str, values: list[object], *, star_count: int | None = None) -> object:
    key = name.lower()
    if key == "count":
        if star_count is not None:
            return star_count
        return sum(1 for v in values if v is not None)
    if key == "sum":
        nums = [v for v in values if v is not None]
        if not nums:
            return None
        if any(isinstance(v, bool) for v in nums):
            raise TypeMismatchError("sum requires numeric input")
        if all(isinstance(v, int) for v in nums):
            return sum(nums)
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in nums):
            return float(sum(float(v) for v in nums))
        raise TypeMismatchError("sum requires numeric input")
    if key == "avg":
        nums = [v for v in values if v is not None]
        if not nums:
            return None
        if any(isinstance(v, bool) for v in nums):
            raise TypeMismatchError("avg requires numeric input")
        if not all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in nums):
            raise TypeMismatchError("avg requires numeric input")
        return sum(float(v) for v in nums) / len(nums)
    if key == "min":
        nums = [v for v in values if v is not None]
        if not nums:
            return None
        if any(isinstance(v, bool) and not isinstance(v, int) for v in nums):
            pass
        if not _compatible(nums):
            raise TypeMismatchError("min requires comparable values")
        current = nums[0]
        for v in nums[1:]:
            if compare_lt(v, current) is True:
                current = v
        return current
    if key == "max":
        nums = [v for v in values if v is not None]
        if not nums:
            return None
        if not _compatible(nums):
            raise TypeMismatchError("max requires comparable values")
        current = nums[0]
        for v in nums[1:]:
            if compare_lt(current, v) is True:
                current = v
        return current
    raise TypeMismatchError(f"unknown aggregate {name}")


def _compatible(values: list[object]) -> bool:
    kinds = {type(v) for v in values}
    if not values:
        return True
    if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
        return True
    if all(isinstance(v, str) for v in values):
        return True
    if all(isinstance(v, bool) for v in values):
        return True
    return False

