def _read_string(text: str, start: int) -> Token:
    i = start + 1
    chars: list[str] = []
    while i < len(text):
        ch = text[i]
        if ch == "'":
            if i + 1 < len(text) and text[i + 1] == "'":
                chars.append("'")
                i += 2
                continue
            return Token("TEXT", "".join(chars), start)
        chars.append(ch)
        i += 1
        if ch == "\n":
            pass
    raise LexError(start)


def _str_value(token: Token) -> str:
    return token.value if isinstance(token.value, str) else ""

